// 1. Get the title from the "Create Post Data2" node for the current item
const title = $('Create Post Data2').item.json.title || 'themeparksavvy-post';

// 2. Get the Pexel URL from the "Pexel Image Url" node for the current item
// (Assuming 'Pexel Image Url' is the correct node name)
const pexelUrl = $('Pexel Image Url').item.json['Photo Landscape'];

// 3. Generate the slug
const slug = title
  .toLowerCase()
  .trim()
  .replace(/[^\w\s-]/g, '') // Remove all non-word chars except spaces and hyphens
  .replace(/[\s_-]+/g, '-') // Replace spaces and underscores with a single hyphen
  .replace(/^[-\s]+|[-\s]+$/g, ''); // Remove leading/trailing hyphens

// 4. Return BOTH the new slug AND the Pexel URL
return {
  slug: slug,
  pexel_url_to_download: pexelUrl
}

// Loop through all the items from the previous node
const cleanList = items.map(item => {
  // Get the title (safely handle if it's missing)
  const title = item.json.title ? item.json.title.rendered : "No Title";

  // Get the direct image link (guid.rendered is the file URL in your screenshot)
  const url = item.json.guid ? item.json.guid.rendered : "No URL";

  // Get the ID (we need this to reference it later)
  const id = item.json.id;

  // Format it as a single line of text
  return `ID: ${id} | Title: "${title}" | URL: ${url}`;
});

// Combine all lines into one big text block for the AI
return [
  {
    json: {
      image_list_for_ai: cleanList.join("\n")
    }
  }
];

