for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return $input.all();

// 1. Get data directly from the input (no more 'referenced node' errors)
const inputData = $input.item.json;

// 2. Extract the title and image URL
// We look for 'title' which we just passed through the chain
const title = inputData.title || 'themeparksavvy-post';
const imageUrl = inputData.image_url; 

// 3. Generate the slug
const slug = title
  .toLowerCase()
  .trim()
  .replace(/[^\w\s-]/g, '') 
  .replace(/[\s_-]+/g, '-') 
  .replace(/^[-\s]+|[-\s]+$/g, ''); 

// 4. Return the results
return {
  slug: slug,
  image_url_to_download: imageUrl 
};

// Get all items from the previous node
const allItems = $input.all();

// Create a formatted list for Gemini
let imageList = "";

const cleanList = allItems.map((item, index) => {
  const title = item.json.title?.rendered || "No Title";
  const url = item.json.guid?.rendered || "No URL";
  const id = item.json.id;

  imageList += `${index + 1}. ID: ${id} | Title: ${title} | URL: ${url}\n`;

  return {
    id: id,
    title: title,
    url: url
  };
});

// Return a single item containing the full list string
return {
  image_list_for_ai: imageList,
  raw_data: cleanList
};

// 1. Get the raw text from Gemini
const rawResponse = $input.first().json.content.parts[0].text.trim();

// 2. Split the ID and URL (e.g., "123|https://sysazzle.com/image.jpg")
const parts = rawResponse.split('|');

if (parts.length < 2) {
  throw new Error("Gemini did not return the ID|URL format correctly.");
}

const imageId = parseInt(parts[0]);
const imageUrl = parts[1];

// 3. Return the clean data to the next node
return {
  media_id: imageId,
  media_url: imageUrl
};

